-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra Carrier Services — combined schema setup.
--
-- Generated by concatenating supabase/migrations/*.sql in filename order.
-- Paste this whole file into the Supabase SQL editor to build the schema in
-- one shot. Every statement is idempotent, so re-running is safe.
--
-- The migrations directory remains the schema of record — regenerate this file
-- after adding one; do not hand-edit it.
-- ─────────────────────────────────────────────────────────────────────────────


-- ===========================================================================
-- 20260803_01_foundation.sql
-- ===========================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra Carrier Services — 01 Foundation: extensions, RLS helper spine,
-- profiles, company_settings, audit_log.
--
-- Run in the Supabase SQL editor in filename order. Every statement is
-- idempotent (safe to re-run). These migrations are the SCHEMA OF RECORD.
--
-- Business model reminder for anyone reading the schema cold: Avantra is a
-- dispatch-service AGENT, not a broker and not an asset carrier. Our CLIENTS are
-- motor carriers (owner-operators / small fleets). We source freight for them
-- from BROKERS, dispatch it on their trucks, invoice the broker on their behalf,
-- and bill the client a DISPATCH FEE. Money flows:
--     broker → client carrier (or their factor)        [the load pays them]
--     client → Avantra                                  [the dispatch fee pays us]
-- ─────────────────────────────────────────────────────────────────────────────

-- Allow the helper functions below to reference tables (profiles) created later
-- in this script — bodies are validated lazily, like pg_dump does. Session-only.
set check_function_bodies = off;

create extension if not exists pgcrypto;   -- gen_random_uuid()

-- ── Generic updated_at trigger ───────────────────────────────────────────────
create or replace function public.set_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end;
$$;

-- ── RLS helper spine (all SECURITY DEFINER so they bypass RLS internally) ─────
create or replace function public.app_role()
returns text language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid()
$$;

create or replace function public.is_master()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select is_master_admin from public.profiles where id = auth.uid()), false)
$$;

-- The workhorse: is the caller Avantra staff (as opposed to a client-portal user)?
create or replace function public.is_staff()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(
    (select is_master_admin
       or role in ('admin','dispatcher','back_office','sales')
     from public.profiles where id = auth.uid()),
    false)
$$;

create or replace function public.has_role(variadic roles text[])
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(
    (select is_master_admin or role = any(roles)
     from public.profiles where id = auth.uid()),
    false)
$$;

-- Drop EVERY existing policy on a table before recreating the intended set, so a
-- stale permissive policy can't survive a re-run.
create or replace function public._reset_policies(tbl text)
returns void language plpgsql as $$
declare p record;
begin
  for p in
    select policyname from pg_policies
    where schemaname = 'public' and tablename = tbl
  loop
    execute format('drop policy if exists %I on public.%I', p.policyname, tbl);
  end loop;
end;
$$;

-- ── profiles ─────────────────────────────────────────────────────────────────
-- PK = auth.users.id. Auto-provisioned at signup (default 'pending'); role +
-- master flag are pinned against self-escalation by the trigger below.
--
-- Roles:
--   admin       — everything
--   dispatcher  — sources + books + dispatches loads, runs the board
--   back_office — invoicing, factoring, invoice tracing/AR, statements, paperwork
--   sales       — prospecting + client onboarding
--   client      — EXTERNAL: a carrier client logging into their own portal
--   pending / terminated — lifecycle states with no data access
create table if not exists public.profiles (
  id              uuid primary key references auth.users(id) on delete cascade,
  email           text,
  full_name       text,
  phone           text,
  role            text not null default 'pending'
                  check (role in ('admin','dispatcher','back_office','sales','client','pending','terminated')),
  is_master_admin boolean not null default false,
  mfa_enrolled    boolean not null default false,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz
);
drop trigger if exists trg_profiles_updated_at on public.profiles;
create trigger trg_profiles_updated_at before update on public.profiles
  for each row execute function public.set_updated_at();

-- Auto-create a profile row when an auth user is created.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, role)
  values (new.id, new.email, 'pending')
  on conflict (id) do nothing;
  return new;
end;
$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Pin role / is_master_admin unless the writer is the service role. RLS is
-- row-level, not column-level, so without this a user could PATCH their own row
-- to admin.
create or replace function public.prevent_profile_privilege_escalation()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.role() = 'service_role' then
    return new;  -- service role (server, role-checked) may change anything
  end if;
  new.role := old.role;
  new.is_master_admin := old.is_master_admin;
  return new;
end;
$$;
drop trigger if exists trg_profiles_priv_esc on public.profiles;
create trigger trg_profiles_priv_esc before update on public.profiles
  for each row execute function public.prevent_profile_privilege_escalation();

alter table public.profiles enable row level security;
select public._reset_policies('profiles');
create policy profiles_select on public.profiles for select
  using (id = auth.uid() or public.is_staff());
create policy profiles_update on public.profiles for update
  using (id = auth.uid() or public.has_role('admin'))
  with check (id = auth.uid() or public.has_role('admin'));
create policy profiles_insert on public.profiles for insert
  with check (public.has_role('admin'));

-- ── company_settings (singleton) ─────────────────────────────────────────────
create table if not exists public.company_settings (
  id                 integer primary key default 1 check (id = 1),
  company_name       text not null default 'Avantra Carrier Services',
  company_identity   jsonb not null default '{}'::jsonb,  -- name/address/logo for PDFs
  role_permissions   jsonb not null default '{}'::jsonb,  -- consumed by @/lib/access
  billing_settings   jsonb not null default '{}'::jsonb,  -- remit-to / ACH for fee statements
  dispatch_defaults  jsonb not null default '{}'::jsonb,  -- default fee %, basis, minimum
  require_2fa        boolean not null default true,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz
);
insert into public.company_settings (id) values (1) on conflict (id) do nothing;
drop trigger if exists trg_company_settings_updated_at on public.company_settings;
create trigger trg_company_settings_updated_at before update on public.company_settings
  for each row execute function public.set_updated_at();

alter table public.company_settings enable row level security;
select public._reset_policies('company_settings');
-- Reads open to any authenticated user (role_permissions is needed everywhere);
-- writes admin/master only.
create policy company_settings_select on public.company_settings for select
  using (auth.uid() is not null);
create policy company_settings_write on public.company_settings for all
  using (public.has_role('admin')) with check (public.has_role('admin'));

-- ── audit_log (append-only, tamper-evident) ─────────────────────────────────
create table if not exists public.audit_log (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references auth.users(id) on delete set null,
  action      text not null,
  table_name  text,
  record_id   text,
  old_value   jsonb,
  new_value   jsonb,
  created_at  timestamptz not null default now()
);
create index if not exists idx_audit_log_created_at on public.audit_log(created_at desc);
create index if not exists idx_audit_log_action on public.audit_log(action);
create index if not exists idx_audit_log_record on public.audit_log(table_name, record_id);

alter table public.audit_log enable row level security;
select public._reset_policies('audit_log');
-- INSERT allowed for any authenticated user, attributed to themselves. No UPDATE
-- or DELETE policy exists → the log is append-only. Reads: admin/back_office.
create policy audit_log_insert on public.audit_log for insert
  with check (user_id = auth.uid());
create policy audit_log_select on public.audit_log for select
  using (public.has_role('admin','back_office'));


-- ===========================================================================
-- 20260803_02_clients.sql
-- ===========================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra — 02 Clients: the carriers we dispatch FOR, plus their drivers,
-- equipment, factoring relationship, and onboarding checklist.
--
-- `clients` is the heart of the model. In Cryolane a carrier is a VENDOR you pay;
-- here a client carrier is the CUSTOMER you serve — you invoice brokers in their
-- name and bill them a dispatch fee. Depends on 01. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

set check_function_bodies = off;

-- ── factoring_companies ──────────────────────────────────────────────────────
-- Most owner-operators factor their receivables. We submit invoices to the
-- client's factor and track funding, so the factor is a first-class entity.
create table if not exists public.factoring_companies (
  id              uuid primary key default gen_random_uuid(),
  name            text not null,
  contact_name    text,
  email           text,
  phone           text,
  submission_email text,               -- where invoice packets get sent
  portal_url      text,
  advance_rate    numeric,             -- e.g. 95.00 (%)
  fee_percent     numeric,             -- e.g. 3.00 (%)
  notes           text,
  is_active       boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz
);
create unique index if not exists idx_factoring_companies_name on public.factoring_companies(lower(name));
drop trigger if exists trg_factoring_companies_updated_at on public.factoring_companies;
create trigger trg_factoring_companies_updated_at before update on public.factoring_companies
  for each row execute function public.set_updated_at();

alter table public.factoring_companies enable row level security;
select public._reset_policies('factoring_companies');
create policy factoring_companies_all on public.factoring_companies for all
  using (public.is_staff()) with check (public.is_staff());

-- ── clients (carrier clients we provide dispatch + back-office services to) ───
create sequence if not exists public.client_number_seq start with 1001;

create table if not exists public.clients (
  id                  uuid primary key default gen_random_uuid(),
  client_number       text unique,
  legal_name          text not null,
  dba_name            text,
  status              text not null default 'prospect'
                      check (status in ('prospect','onboarding','active','paused','terminated')),
  -- Authority / identity
  mc_number           text,
  dot_number          text,
  ein                 text,
  authority_status    text not null default 'unknown'
                      check (authority_status in ('active','pending','inactive','not_authorized','unknown')),
  authority_date      date,
  safety_rating       text,
  fmcsa_last_checked  timestamptz,
  -- Contact
  contact_name        text,
  phone               text,
  email               text,
  billing_email       text,
  address             text,
  city                text,
  state               text,
  zip                 text,
  -- Service agreement — the legal spine of the agent relationship
  agreement_signed_at date,
  poa_signed_at       date,            -- limited power of attorney (bill in their name)
  agreement_doc_path  text,            -- private `documents` bucket object path
  w9_on_file          boolean not null default false,
  coi_on_file         boolean not null default false,
  noa_on_file         boolean not null default false,   -- notice of assignment (factoring)
  -- Dispatch fee terms (snapshotted onto each load at booking)
  fee_type            text not null default 'percent' check (fee_type in ('percent','flat')),
  fee_percent         numeric not null default 10,
  fee_flat            numeric not null default 0,
  fee_basis           text not null default 'gross' check (fee_basis in ('gross','linehaul')),
  fee_minimum         numeric not null default 0,
  billing_cycle       text not null default 'weekly' check (billing_cycle in ('weekly','biweekly','monthly','per_load')),
  -- Factoring
  factoring_company_id uuid references public.factoring_companies(id) on delete set null,
  factors_invoices    boolean not null default false,
  -- Insurance (COI tracking lives in compliance_items; these are the quick-glance fields)
  insurance_provider  text,
  liability_amount    numeric,
  cargo_amount        numeric,
  insurance_expiry    date,
  -- Dispatch preferences — what the dispatcher needs to know before booking
  equipment_types     text[] not null default '{}',      -- Reefer / Dry Van / Flatbed …
  preferred_states    text[] not null default '{}',
  avoid_states        text[] not null default '{}',
  home_base_city      text,
  home_base_state     text,
  min_rate_per_mile   numeric,
  max_weekly_miles    numeric,
  hazmat              boolean not null default false,
  team                boolean not null default false,
  notes               text,
  -- Ownership
  assigned_dispatcher uuid references auth.users(id) on delete set null,
  onboarded_at        date,
  terminated_at       date,
  termination_reason  text,
  deleted_at          timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz
);
create index if not exists idx_clients_status on public.clients(status) where deleted_at is null;
create index if not exists idx_clients_dispatcher on public.clients(assigned_dispatcher);
create index if not exists idx_clients_mc on public.clients(mc_number);
create index if not exists idx_clients_name on public.clients(lower(legal_name));

create or replace function public.set_client_number()
returns trigger language plpgsql as $$
begin
  if new.client_number is null or new.client_number = '' then
    new.client_number := 'AC-' || nextval('public.client_number_seq');
  end if;
  return new;
end;
$$;
drop trigger if exists trg_clients_set_number on public.clients;
create trigger trg_clients_set_number before insert on public.clients
  for each row execute function public.set_client_number();
drop trigger if exists trg_clients_updated_at on public.clients;
create trigger trg_clients_updated_at before update on public.clients
  for each row execute function public.set_updated_at();

alter table public.clients enable row level security;
select public._reset_policies('clients');
create policy clients_staff_all on public.clients for all
  using (public.is_staff()) with check (public.is_staff());

-- ── Client-portal identity ───────────────────────────────────────────────────
-- A 'client' role profile is bound to exactly one client row. Every portal RLS
-- policy funnels through app_client_id() so a client can only ever see their own
-- data. Added here (not in 01) because it needs clients to exist for the FK.
alter table public.profiles
  add column if not exists client_id uuid references public.clients(id) on delete set null;

create or replace function public.app_client_id()
returns uuid language sql stable security definer set search_path = public as $$
  select client_id from public.profiles where id = auth.uid()
$$;

-- Clients may read their own record (never write it).
create policy clients_portal_select on public.clients for select
  using (id = public.app_client_id());

-- ── client_drivers ───────────────────────────────────────────────────────────
create table if not exists public.client_drivers (
  id              uuid primary key default gen_random_uuid(),
  client_id       uuid not null references public.clients(id) on delete cascade,
  full_name       text not null,
  phone           text,
  email           text,
  cdl_number      text,
  cdl_state       text,
  cdl_expiry      date,
  medical_expiry  date,
  hazmat_endorsed boolean not null default false,
  is_owner        boolean not null default false,   -- the O-O themself drives
  status          text not null default 'active' check (status in ('active','inactive','terminated')),
  notes           text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz
);
create index if not exists idx_client_drivers_client on public.client_drivers(client_id);
create index if not exists idx_client_drivers_cdl_expiry on public.client_drivers(cdl_expiry) where cdl_expiry is not null;
drop trigger if exists trg_client_drivers_updated_at on public.client_drivers;
create trigger trg_client_drivers_updated_at before update on public.client_drivers
  for each row execute function public.set_updated_at();

alter table public.client_drivers enable row level security;
select public._reset_policies('client_drivers');
create policy client_drivers_staff_all on public.client_drivers for all
  using (public.is_staff()) with check (public.is_staff());
create policy client_drivers_portal_select on public.client_drivers for select
  using (client_id = public.app_client_id());

-- ── client_equipment (their trucks + trailers) ───────────────────────────────
create table if not exists public.client_equipment (
  id              uuid primary key default gen_random_uuid(),
  client_id       uuid not null references public.clients(id) on delete cascade,
  kind            text not null default 'truck' check (kind in ('truck','trailer')),
  unit_number     text,
  equipment_type  text,               -- Reefer / Dry Van / Flatbed / Step Deck …
  year            integer,
  make            text,
  model           text,
  vin             text,
  plate           text,
  plate_state     text,
  length_ft       integer,
  status          text not null default 'active' check (status in ('active','inactive','out_of_service')),
  notes           text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz
);
create index if not exists idx_client_equipment_client on public.client_equipment(client_id, kind);
drop trigger if exists trg_client_equipment_updated_at on public.client_equipment;
create trigger trg_client_equipment_updated_at before update on public.client_equipment
  for each row execute function public.set_updated_at();

alter table public.client_equipment enable row level security;
select public._reset_policies('client_equipment');
create policy client_equipment_staff_all on public.client_equipment for all
  using (public.is_staff()) with check (public.is_staff());
create policy client_equipment_portal_select on public.client_equipment for select
  using (client_id = public.app_client_id());

-- ── client_onboarding_steps ──────────────────────────────────────────────────
-- The A-to-Z onboarding checklist. Seeded per client from a default template by
-- the app; each row is independently completable and auditable.
create table if not exists public.client_onboarding_steps (
  id           uuid primary key default gen_random_uuid(),
  client_id    uuid not null references public.clients(id) on delete cascade,
  step_key     text not null,          -- agreement | poa | w9 | coi | noa | authority | setup_packet …
  label        text not null,
  sort_order   integer not null default 0,
  is_required  boolean not null default true,
  completed_at timestamptz,
  completed_by uuid references auth.users(id) on delete set null,
  doc_path     text,
  notes        text,
  created_at   timestamptz not null default now()
);
create unique index if not exists idx_onboarding_client_step on public.client_onboarding_steps(client_id, step_key);
create index if not exists idx_onboarding_client on public.client_onboarding_steps(client_id, sort_order);

alter table public.client_onboarding_steps enable row level security;
select public._reset_policies('client_onboarding_steps');
create policy client_onboarding_staff_all on public.client_onboarding_steps for all
  using (public.is_staff()) with check (public.is_staff());
create policy client_onboarding_portal_select on public.client_onboarding_steps for select
  using (client_id = public.app_client_id());

-- ── client_notes (CRM timeline) ──────────────────────────────────────────────
create table if not exists public.client_notes (
  id         uuid primary key default gen_random_uuid(),
  client_id  uuid not null references public.clients(id) on delete cascade,
  body       text not null,
  kind       text not null default 'note' check (kind in ('note','call','email','meeting','issue')),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists idx_client_notes_client on public.client_notes(client_id, created_at desc);

alter table public.client_notes enable row level security;
select public._reset_policies('client_notes');
create policy client_notes_staff_all on public.client_notes for all
  using (public.is_staff()) with check (public.is_staff());


-- ===========================================================================
-- 20260803_03_brokers_loads.sql
-- ===========================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra — 03 Brokers + Loads: the counterparties we book with, the central
-- load fact table, multi-stop support, and the check-call log.
--
-- Money on a load runs the OPPOSITE direction from a brokerage. The broker pays
-- the GROSS to our client (or their factor). We take a DISPATCH FEE off that
-- gross; net_to_client is what the carrier keeps. There is no margin — our
-- revenue is dispatch_fee, full stop. Depends on 01–02. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

set check_function_bodies = off;

-- ── brokers (who pays the freight bill) ──────────────────────────────────────
create table if not exists public.brokers (
  id                uuid primary key default gen_random_uuid(),
  name              text not null,
  mc_number         text,
  dot_number        text,
  -- Contact
  contact_name      text,
  phone             text,
  after_hours_phone text,
  email             text,
  billing_email     text,
  address           text,
  city              text,
  state             text,
  zip               text,
  -- Credit / payment behaviour — what makes a broker safe to haul for
  payment_terms     text,                       -- "Net 30", "Quick Pay 2%" …
  days_to_pay       integer,                    -- observed average, updated from paid invoices
  credit_rating     text,                       -- free-text (Ansonia / broker credit score)
  credit_limit      numeric,
  -- Setup packet: are we able to invoice them on a client's behalf yet?
  packet_status     text not null default 'none'
                    check (packet_status in ('none','sent','pending','complete')),
  packet_completed_at date,
  -- Blocklist
  do_not_use        boolean not null default false,
  do_not_use_reason text,
  notes             text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz
);
create index if not exists idx_brokers_name on public.brokers(lower(name));
create index if not exists idx_brokers_mc on public.brokers(mc_number);
create index if not exists idx_brokers_dnu on public.brokers(do_not_use) where do_not_use = true;
drop trigger if exists trg_brokers_updated_at on public.brokers;
create trigger trg_brokers_updated_at before update on public.brokers
  for each row execute function public.set_updated_at();

alter table public.brokers enable row level security;
select public._reset_policies('brokers');
create policy brokers_staff_all on public.brokers for all
  using (public.is_staff()) with check (public.is_staff());

-- ── loads ────────────────────────────────────────────────────────────────────
-- Single-pickup/single-drop details live denormalized on the load itself (the
-- common case, and it keeps the board query to one table). Extra stops go in
-- load_stops; the denormalized columns always mirror the FIRST pickup and LAST
-- delivery so lists and the public tracking page never need the join.
create sequence if not exists public.load_number_seq start with 10001;

create table if not exists public.loads (
  id                 uuid primary key default gen_random_uuid(),
  load_number        text unique,
  status             text not null default 'sourced'
                     check (status in ('sourced','offered','booked','dispatched','at_pickup',
                                       'in_transit','at_delivery','delivered','docs_received',
                                       'invoiced','paid','cancelled','tonu')),
  -- Who it's for / who pays
  client_id          uuid references public.clients(id) on delete set null,
  client_name        text,
  broker_id          uuid references public.brokers(id) on delete set null,
  broker_name        text,
  broker_load_number text,
  source             text not null default 'broker_direct'
                     check (source in ('dat','truckstop','broker_direct','client','relationship','other')),
  -- Assignment (the client's own driver + equipment)
  driver_id          uuid references public.client_drivers(id) on delete set null,
  driver_name        text,
  truck_id           uuid references public.client_equipment(id) on delete set null,
  trailer_id         uuid references public.client_equipment(id) on delete set null,
  -- Pickup (first stop)
  shipper_name       text,
  shipper_address    text,
  pickup_city        text,
  pickup_state       text,
  pickup_zip         text,
  pickup_date        date,
  pickup_time        text,
  pickup_appt        text,
  -- Delivery (last stop)
  consignee_name     text,
  consignee_address  text,
  delivery_city      text,
  delivery_state     text,
  delivery_zip       text,
  delivery_date      date,
  delivery_time      text,
  delivery_appt      text,
  -- Freight
  commodity          text,
  weight             numeric,
  temperature        text,
  equipment_type     text,
  miles              numeric,
  stop_count         integer not null default 2,
  -- Money the BROKER pays (all revenue belongs to the client, not to us)
  line_haul          numeric not null default 0,
  fuel_surcharge     numeric not null default 0,
  accessorials       numeric not null default 0,
  detention          numeric not null default 0,
  lumper             numeric not null default 0,
  other_charges      numeric not null default 0,
  gross_total        numeric not null default 0,   -- maintained by recalc_load_money()
  -- Dispatch fee terms, SNAPSHOTTED from the client at booking so changing the
  -- client's plan later never rewrites history.
  fee_type           text not null default 'percent' check (fee_type in ('percent','flat')),
  fee_percent        numeric not null default 10,
  fee_flat           numeric not null default 0,
  fee_basis          text not null default 'gross' check (fee_basis in ('gross','linehaul')),
  fee_minimum        numeric not null default 0,
  fee_manual         boolean not null default false,  -- true = dispatch_fee entered by hand
  fee_waived         boolean not null default false,
  fee_waived_reason  text,
  dispatch_fee       numeric not null default 0,   -- OUR revenue. maintained by trigger
  net_to_client      numeric not null default 0,   -- gross_total − dispatch_fee
  -- References / paperwork
  ref_number         text,
  po_number          text,
  bol_number         text,
  seal_number        text,
  rate_con_path      text,                          -- private `documents` object path
  rate_con_received_at timestamptz,
  pod_path           text,
  pod_received_at    timestamptz,
  -- Lifecycle timestamps
  offered_at         timestamptz,
  booked_at          timestamptz,
  dispatched_at      timestamptz,
  picked_up_at       timestamptz,
  delivered_at       timestamptz,
  cancelled_at       timestamptz,
  cancel_reason      text,
  -- Public tracking
  tracking_token     uuid not null default gen_random_uuid(),
  tracking_active    boolean not null default true,
  notes              text,
  dispatcher_id      uuid references auth.users(id) on delete set null,
  deleted_at         timestamptz,
  deleted_by         uuid references auth.users(id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz
);
create unique index if not exists idx_loads_tracking_token on public.loads(tracking_token);
create index if not exists idx_loads_status on public.loads(status) where deleted_at is null;
create index if not exists idx_loads_client on public.loads(client_id) where deleted_at is null;
create index if not exists idx_loads_broker on public.loads(broker_id) where deleted_at is null;
create index if not exists idx_loads_driver on public.loads(driver_id) where deleted_at is null;
create index if not exists idx_loads_pickup_date on public.loads(pickup_date desc);
create index if not exists idx_loads_lane on public.loads(pickup_state, delivery_state);

-- Auto load number.
create or replace function public.set_load_number()
returns trigger language plpgsql as $$
begin
  if new.load_number is null or new.load_number = '' then
    new.load_number := 'AV-' || nextval('public.load_number_seq');
  end if;
  return new;
end;
$$;

-- ── The money engine ─────────────────────────────────────────────────────────
-- A trigger rather than generated columns: the fee needs a minimum, a manual
-- override, and a waive path, none of which a generated column can express
-- (and Postgres forbids a generated column referencing another one anyway).
create or replace function public.recalc_load_money()
returns trigger language plpgsql as $$
declare
  v_gross numeric;
  v_base  numeric;
  v_fee   numeric;
begin
  v_gross := coalesce(new.line_haul,0) + coalesce(new.fuel_surcharge,0)
           + coalesce(new.accessorials,0) + coalesce(new.detention,0)
           + coalesce(new.lumper,0) + coalesce(new.other_charges,0);

  if new.fee_waived or new.status = 'cancelled' then
    v_fee := 0;
  elsif new.fee_manual then
    v_fee := coalesce(new.dispatch_fee, 0);          -- respect the hand-entered value
  else
    v_base := case when new.fee_basis = 'linehaul'
                   then coalesce(new.line_haul, 0)
                   else v_gross end;
    v_fee  := case when new.fee_type = 'flat'
                   then coalesce(new.fee_flat, 0)
                   else round(v_base * coalesce(new.fee_percent, 0) / 100.0, 2) end;
    -- A minimum only applies once there's actually money on the load, so a blank
    -- draft doesn't show a fee owed.
    if coalesce(new.fee_minimum, 0) > 0 and v_base > 0 then
      v_fee := greatest(v_fee, new.fee_minimum);
    end if;
  end if;

  new.gross_total   := round(v_gross, 2);
  new.dispatch_fee  := round(v_fee, 2);
  new.net_to_client := round(v_gross - v_fee, 2);
  return new;
end;
$$;

drop trigger if exists trg_loads_set_number on public.loads;
create trigger trg_loads_set_number before insert on public.loads
  for each row execute function public.set_load_number();
drop trigger if exists trg_loads_money on public.loads;
create trigger trg_loads_money before insert or update on public.loads
  for each row execute function public.recalc_load_money();
drop trigger if exists trg_loads_updated_at on public.loads;
create trigger trg_loads_updated_at before update on public.loads
