create policy invoices_portal_select on public.invoices for select
  using (client_id = public.app_client_id());

-- ── invoice_traces (the collections activity log) ────────────────────────────
-- Every chase attempt against a broker invoice. Keeping this append-only-ish and
-- attributed is what lets us show a client exactly what we did to get them paid.
create table if not exists public.invoice_traces (
  id            uuid primary key default gen_random_uuid(),
  invoice_id    uuid not null references public.invoices(id) on delete cascade,
  traced_at     timestamptz not null default now(),
  method        text not null default 'call' check (method in ('call','email','portal','letter','other')),
  contact_name  text,
  contact_info  text,
  outcome       text not null default 'no_answer'
                check (outcome in ('no_answer','left_message','promised_payment','in_process',
                                   'disputed','short_paid','paid','escalated','other')),
  promised_date date,
  notes         text,
  created_by    uuid references auth.users(id) on delete set null,
  created_at    timestamptz not null default now()
);
create index if not exists idx_invoice_traces_invoice on public.invoice_traces(invoice_id, traced_at desc);

-- Keep the invoice's rollup counters honest without the app having to remember.
create or replace function public.bump_invoice_trace_counters()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.invoices
     set trace_count    = (select count(*) from public.invoice_traces where invoice_id = new.invoice_id),
         last_traced_at = (select max(traced_at) from public.invoice_traces where invoice_id = new.invoice_id),
         next_follow_up = coalesce(new.promised_date, next_follow_up)
   where id = new.invoice_id;
  return new;
end;
$$;
drop trigger if exists trg_invoice_traces_bump on public.invoice_traces;
create trigger trg_invoice_traces_bump after insert on public.invoice_traces
  for each row execute function public.bump_invoice_trace_counters();

alter table public.invoice_traces enable row level security;
select public._reset_policies('invoice_traces');
create policy invoice_traces_staff_all on public.invoice_traces for all
  using (public.is_staff()) with check (public.is_staff());
create policy invoice_traces_portal_select on public.invoice_traces for select
  using (exists (select 1 from public.invoices i
                 where i.id = invoice_id and i.client_id = public.app_client_id()));

-- ── client_statements (Avantra's revenue: the dispatch-fee bill) ─────────────
create sequence if not exists public.statement_number_seq start with 2001;

create table if not exists public.client_statements (
  id                uuid primary key default gen_random_uuid(),
  statement_number  text unique,
  client_id         uuid not null references public.clients(id) on delete cascade,
  period_start      date not null,
  period_end        date not null,
  status            text not null default 'draft'
                    check (status in ('draft','sent','partial','paid','overdue','void')),
  load_count        integer not null default 0,
  total_gross       numeric not null default 0,   -- gross the client billed on these loads
  total_fees        numeric not null default 0,   -- our fees on those loads
  adjustments       numeric not null default 0,   -- credits/discounts (negative) or add-ons
  amount_due        numeric not null default 0,   -- total_fees + adjustments
  amount_paid       numeric not null default 0,
  issued_date       date,
  due_date          date,
  sent_at           timestamptz,
  paid_date         date,
  payment_method    text check (payment_method in ('ach','check','wire','card','other')),
  payment_reference text,
  pdf_path          text,
  voided_at         timestamptz,
  voided_by         uuid references auth.users(id) on delete set null,
  void_reason       text,
  notes             text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz
);
create index if not exists idx_statements_client on public.client_statements(client_id, period_end desc);
create index if not exists idx_statements_status on public.client_statements(status);

create or replace function public.set_statement_number()
returns trigger language plpgsql as $$
begin
  if new.statement_number is null or new.statement_number = '' then
    new.statement_number := 'ST-' || nextval('public.statement_number_seq');
  end if;
  return new;
end;
$$;
drop trigger if exists trg_statements_set_number on public.client_statements;
create trigger trg_statements_set_number before insert on public.client_statements
  for each row execute function public.set_statement_number();
drop trigger if exists trg_statements_updated_at on public.client_statements;
create trigger trg_statements_updated_at before update on public.client_statements
  for each row execute function public.set_updated_at();

alter table public.client_statements enable row level security;
select public._reset_policies('client_statements');
create policy client_statements_staff_all on public.client_statements for all
  using (public.is_staff()) with check (public.is_staff());
create policy client_statements_portal_select on public.client_statements for select
  using (client_id = public.app_client_id());

-- ── statement_lines ──────────────────────────────────────────────────────────
create table if not exists public.statement_lines (
  id           uuid primary key default gen_random_uuid(),
  statement_id uuid not null references public.client_statements(id) on delete cascade,
  load_id      uuid references public.loads(id) on delete set null,
  kind         text not null default 'fee' check (kind in ('fee','adjustment','credit','service')),
  description  text not null,
  load_gross   numeric not null default 0,
  amount       numeric not null default 0,   -- what the client owes for this line
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now()
);
create index if not exists idx_statement_lines_statement on public.statement_lines(statement_id, sort_order);
-- A load's fee can only land on one statement, so a re-run can't double-bill.
create unique index if not exists idx_statement_lines_one_fee_per_load
  on public.statement_lines(load_id) where load_id is not null and kind = 'fee';

-- Recompute the statement header whenever its lines change.
create or replace function public.recalc_statement_totals()
returns trigger language plpgsql security definer set search_path = public as $$
declare v_stmt uuid;
begin
  v_stmt := coalesce(new.statement_id, old.statement_id);
  update public.client_statements s
     set load_count  = (select count(*) from public.statement_lines
                        where statement_id = v_stmt and kind = 'fee'),
         total_gross = (select coalesce(sum(load_gross),0) from public.statement_lines
                        where statement_id = v_stmt and kind = 'fee'),
         total_fees  = (select coalesce(sum(amount),0) from public.statement_lines
                        where statement_id = v_stmt and kind = 'fee'),
         adjustments = (select coalesce(sum(amount),0) from public.statement_lines
                        where statement_id = v_stmt and kind <> 'fee'),
         amount_due  = (select coalesce(sum(amount),0) from public.statement_lines
                        where statement_id = v_stmt)
   where s.id = v_stmt;
  return null;
end;
$$;
drop trigger if exists trg_statement_lines_recalc on public.statement_lines;
create trigger trg_statement_lines_recalc
  after insert or update or delete on public.statement_lines
  for each row execute function public.recalc_statement_totals();

alter table public.statement_lines enable row level security;
select public._reset_policies('statement_lines');
create policy statement_lines_staff_all on public.statement_lines for all
  using (public.is_staff()) with check (public.is_staff());
create policy statement_lines_portal_select on public.statement_lines for select
  using (exists (select 1 from public.client_statements s
                 where s.id = statement_id and s.client_id = public.app_client_id()));


-- ===========================================================================
-- 20260803_05_compliance_services.sql
-- ===========================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra — 05 Compliance + Service Requests.
--
-- compliance_items is a single generic expiry ledger covering everything Avantra
-- watches on a client's behalf: operating authority, liability/cargo COIs, IFTA,
-- UCR, MCS-150, BOC-3, drug consortium, 2290, CDLs, medical cards, annual
-- inspections. One table (not one per kind) so the watchdog is a single query and
-- adding a new kind never needs a migration.
--
-- service_requests is the back-office work queue that makes "A-to-Z services"
-- real: every non-load thing a client asks us to do, tracked, assigned, and
-- optionally billable onto their statement. Depends on 01–04. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

set check_function_bodies = off;

-- ── compliance_items ─────────────────────────────────────────────────────────
create table if not exists public.compliance_items (
  id            uuid primary key default gen_random_uuid(),
  client_id     uuid not null references public.clients(id) on delete cascade,
  -- What the item hangs off. client_id is ALWAYS set (even for a driver's CDL) so
  -- the compliance board can filter by client without extra joins.
  entity_type   text not null default 'client'
                check (entity_type in ('client','driver','equipment')),
  entity_id     uuid,
  kind          text not null,        -- authority | liability_insurance | cargo_insurance |
                                      -- ifta | ucr | mcs150 | boc3 | drug_consortium |
                                      -- form_2290 | cdl | medical_card | annual_inspection | other
  label         text,                 -- human override, else the app renders the kind
  status        text not null default 'pending'
                check (status in ('ok','expiring','expired','missing','pending','not_applicable')),
  provider      text,                 -- insurer / consortium / filing agent
  reference     text,                 -- policy #, filing #, confirmation #
  amount        numeric,              -- coverage limit where relevant
  effective_date date,
  expiry_date   date,
  doc_path      text,                 -- private `documents` object path
  last_checked_at timestamptz,
  notes         text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz
);
create index if not exists idx_compliance_client on public.compliance_items(client_id, kind);
create index if not exists idx_compliance_expiry on public.compliance_items(expiry_date)
  where expiry_date is not null;
create index if not exists idx_compliance_status on public.compliance_items(status);
create unique index if not exists idx_compliance_unique
  on public.compliance_items(client_id, entity_type, coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid), kind);

drop trigger if exists trg_compliance_updated_at on public.compliance_items;
create trigger trg_compliance_updated_at before update on public.compliance_items
  for each row execute function public.set_updated_at();

-- Derive status from the expiry date on every write, so the board is never stale
-- because someone forgot to also flip the status field.
create or replace function public.derive_compliance_status()
returns trigger language plpgsql as $$
begin
  if new.status = 'not_applicable' then
    return new;                                    -- explicit opt-out wins
  end if;
  if new.expiry_date is null then
    if new.effective_date is null and new.reference is null and new.doc_path is null then
      new.status := 'missing';
    else
      new.status := 'ok';
    end if;
  elsif new.expiry_date < current_date then
    new.status := 'expired';
  elsif new.expiry_date <= current_date + interval '30 days' then
    new.status := 'expiring';
  else
    new.status := 'ok';
  end if;
  return new;
end;
$$;
drop trigger if exists trg_compliance_status on public.compliance_items;
create trigger trg_compliance_status before insert or update on public.compliance_items
  for each row execute function public.derive_compliance_status();

alter table public.compliance_items enable row level security;
select public._reset_policies('compliance_items');
create policy compliance_staff_all on public.compliance_items for all
  using (public.is_staff()) with check (public.is_staff());
create policy compliance_portal_select on public.compliance_items for select
  using (client_id = public.app_client_id());

-- ── service_requests ─────────────────────────────────────────────────────────
create sequence if not exists public.service_request_seq start with 101;

create table if not exists public.service_requests (
  id            uuid primary key default gen_random_uuid(),
  request_number text unique,
  client_id     uuid references public.clients(id) on delete cascade,
  kind          text not null default 'other',
                -- new_authority | authority_reinstatement | ifta_registration | ifta_filing |
                -- ucr | mcs150_update | boc3 | drug_consortium | form_2290 | insurance_quote |
                -- factoring_setup | broker_setup | permit | dispute | notary | other
  title         text not null,
  description   text,
  status        text not null default 'open'
                check (status in ('open','in_progress','waiting_client','waiting_third_party',
                                  'blocked','done','cancelled')),
  priority      text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  assigned_to   uuid references auth.users(id) on delete set null,
  requested_by  uuid references auth.users(id) on delete set null,
  due_date      date,
  started_at    timestamptz,
  completed_at  timestamptz,
  -- Billable services flow onto the client's next statement as a 'service' line.
  billable      boolean not null default false,
  fee_amount    numeric not null default 0,
  billed_at     timestamptz,
  statement_id  uuid references public.client_statements(id) on delete set null,
  outcome       text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz
);
create index if not exists idx_service_requests_client on public.service_requests(client_id);
create index if not exists idx_service_requests_status on public.service_requests(status, priority);
create index if not exists idx_service_requests_assignee on public.service_requests(assigned_to)
  where status not in ('done','cancelled');
create index if not exists idx_service_requests_billable on public.service_requests(billable)
  where billable = true and billed_at is null;

create or replace function public.set_service_request_number()
returns trigger language plpgsql as $$
begin
  if new.request_number is null or new.request_number = '' then
    new.request_number := 'SR-' || nextval('public.service_request_seq');
  end if;
  return new;
end;
$$;
drop trigger if exists trg_service_requests_set_number on public.service_requests;
create trigger trg_service_requests_set_number before insert on public.service_requests
  for each row execute function public.set_service_request_number();
drop trigger if exists trg_service_requests_updated_at on public.service_requests;
create trigger trg_service_requests_updated_at before update on public.service_requests
  for each row execute function public.set_updated_at();

alter table public.service_requests enable row level security;
select public._reset_policies('service_requests');
create policy service_requests_staff_all on public.service_requests for all
  using (public.is_staff()) with check (public.is_staff());
create policy service_requests_portal_select on public.service_requests for select
  using (client_id = public.app_client_id());

-- ── service_request_updates (per-request timeline) ───────────────────────────
create table if not exists public.service_request_updates (
  id          uuid primary key default gen_random_uuid(),
  request_id  uuid not null references public.service_requests(id) on delete cascade,
  body        text not null,
  status_from text,
  status_to   text,
  created_by  uuid references auth.users(id) on delete set null,
  created_at  timestamptz not null default now()
);
create index if not exists idx_sr_updates_request on public.service_request_updates(request_id, created_at desc);

alter table public.service_request_updates enable row level security;
select public._reset_policies('service_request_updates');
create policy sr_updates_staff_all on public.service_request_updates for all
  using (public.is_staff()) with check (public.is_staff());
create policy sr_updates_portal_select on public.service_request_updates for select
  using (exists (select 1 from public.service_requests r
                 where r.id = request_id and r.client_id = public.app_client_id()));


-- ===========================================================================
-- 20260803_06_documents_tracking.sql
-- ===========================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra — 06 Documents + public tracking.
--
-- The `documents` storage bucket is PRIVATE. Nothing in the app ever calls
-- getPublicUrl(); files are read exclusively through short-lived signed URLs
-- minted server-side by /api/doc-url. The table below is metadata only — the
-- bytes live in storage.
--
-- The /track/<token> page is anonymous, so it reads through SECURITY DEFINER
-- RPCs that whitelist safe columns. Rates, fees, and net-to-client are NEVER
-- exposed — a broker holding a tracking link must not be able to see what our
-- client is netting, or what we charge. Depends on 01–05. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

set check_function_bodies = off;

-- ── documents (metadata for objects in the private `documents` bucket) ───────
create table if not exists public.documents (
  id            uuid primary key default gen_random_uuid(),
  entity_type   text not null
                check (entity_type in ('client','driver','equipment','load','broker',
                                       'invoice','statement','service_request','company')),
  entity_id     uuid,
  -- Denormalized so portal RLS is a single column compare rather than a
  -- polymorphic join per entity_type.
  client_id     uuid references public.clients(id) on delete cascade,
  doc_type      text not null default 'other',
                -- rate_con | bol | pod | invoice | w9 | coi | authority | agreement |
                -- poa | noa | cdl | medical | inspection | lumper_receipt | scale | other
  file_path     text not null,        -- bare object path in the private bucket
  file_name     text,
  mime_type     text,
  size_bytes    bigint,
  expiry_date   date,                 -- for COIs and other expiring paperwork
  is_client_visible boolean not null default true,
  notes         text,
  uploaded_by   uuid references auth.users(id) on delete set null,
  created_at    timestamptz not null default now()
);
create index if not exists idx_documents_entity on public.documents(entity_type, entity_id);
create index if not exists idx_documents_client on public.documents(client_id);
create index if not exists idx_documents_type on public.documents(doc_type);
create index if not exists idx_documents_expiry on public.documents(expiry_date)
  where expiry_date is not null;

alter table public.documents enable row level security;
select public._reset_policies('documents');
create policy documents_staff_all on public.documents for all
  using (public.is_staff()) with check (public.is_staff());
create policy documents_portal_select on public.documents for select
  using (client_id = public.app_client_id() and is_client_visible = true);

-- ── The private bucket ───────────────────────────────────────────────────────
-- public = false. Signed URLs are minted by the service role in /api/doc-url,
-- which is why no broad storage.objects policy is granted to end users.
insert into storage.buckets (id, name, public)
values ('documents', 'documents', false)
on conflict (id) do update set public = false;

-- Staff may upload / read / delete objects in the bucket via their own session
-- (the client-side uploader); everyone else goes through the signed-URL route.
drop policy if exists documents_bucket_staff_all on storage.objects;
create policy documents_bucket_staff_all on storage.objects for all
  to authenticated
  using (bucket_id = 'documents' and public.is_staff())
  with check (bucket_id = 'documents' and public.is_staff());

-- ── Public tracking RPCs ─────────────────────────────────────────────────────
-- Whitelisted columns only. Deliberately omits line_haul, gross_total,
-- dispatch_fee, net_to_client, broker identity, and internal notes.
create or replace function public.get_load_tracking(p_token uuid)
returns table (
  load_number     text,
  status          text,
  equipment_type  text,
  client_name     text,
  pickup_city     text,
  pickup_state    text,
  pickup_date     date,
  delivery_city   text,
  delivery_state  text,
  delivery_date   date,
  commodity       text,
  temperature     text,
  stop_count      integer,
  tracking_active boolean
)
language sql stable security definer set search_path = public as $$
  select load_number, status, equipment_type, client_name,
         pickup_city, pickup_state, pickup_date,
         delivery_city, delivery_state, delivery_date,
         commodity, temperature, stop_count, tracking_active
  from public.loads
  where tracking_token = p_token
    and tracking_active = true
    and deleted_at is null
$$;
revoke all on function public.get_load_tracking(uuid) from public;
grant execute on function public.get_load_tracking(uuid) to anon, authenticated;

-- Check-in feed for the tracking page: only is_public rows, and never the
-- internal `notes` column.
create or replace function public.get_load_tracking_events(p_token uuid)
returns table (occurred_at timestamptz, location text, city text, state text,
               status_note text, temperature text, eta timestamptz)
language sql stable security definer set search_path = public as $$
  select cc.occurred_at, cc.location, cc.city, cc.state,
         cc.status_note, cc.temperature, cc.eta
  from public.load_check_calls cc
  join public.loads l on l.id = cc.load_id
  where l.tracking_token = p_token
    and l.tracking_active = true
    and l.deleted_at is null
    and cc.is_public = true
  order by cc.occurred_at desc
  limit 50
$$;
revoke all on function public.get_load_tracking_events(uuid) from public;
grant execute on function public.get_load_tracking_events(uuid) to anon, authenticated;


-- ===========================================================================
-- 20260908_07_leads.sql
-- ===========================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra — 07 Leads: enquiries from the marketing site (avantracs.com).
--
-- The marketing site is a SEPARATE deploy but writes into this same project, so
-- a lead lands in the dispatch queue rather than an inbox somebody has to
-- remember to check.
--
-- Security posture: the website has NO browser-side Supabase client and no anon
-- key. Its /api/lead route writes with the service role, server-side only. So
-- there is deliberately NO anon INSERT policy here — the table has no public
-- write surface at all, and spam control lives in the route (honeypot + rate
-- limit) rather than in RLS.
--
-- Depends on 01 (helpers) and 02 (clients). Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

set check_function_bodies = off;

create table if not exists public.leads (
  id            uuid primary key default gen_random_uuid(),
  -- Who got in touch
  name          text not null,
  company       text,
  email         text not null,
  phone         text,
  mc_number     text,
  equipment     text,
  truck_count   integer,
  message       text,
  -- Where from
  source        text not null default 'website'
                check (source in ('website','referral','phone','load_board','other')),
  submitted_ip  text,                 -- abuse triage only; never displayed
  -- Working the lead
  status        text not null default 'new'
                check (status in ('new','contacted','quoted','won','lost','spam')),
  assigned_to   uuid references auth.users(id) on delete set null,
  notes         text,
  contacted_at  timestamptz,
  -- Set when the lead becomes a real client, so the link survives conversion.
  converted_client_id uuid references public.clients(id) on delete set null,
  converted_at  timestamptz,
  lost_reason   text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz
);

create index if not exists idx_leads_status on public.leads(status, created_at desc);
create index if not exists idx_leads_created on public.leads(created_at desc);
create index if not exists idx_leads_email on public.leads(lower(email));

drop trigger if exists trg_leads_updated_at on public.leads;
create trigger trg_leads_updated_at before update on public.leads
  for each row execute function public.set_updated_at();

-- Stamp contacted_at the first time a lead leaves 'new', so nobody has to
-- remember to set it and response-time reporting stays honest.
create or replace function public.stamp_lead_contacted()
returns trigger language plpgsql as $$
begin
  if new.status is distinct from old.status
     and old.status = 'new'
     and new.status <> 'new'
     and new.contacted_at is null then
    new.contacted_at := now();
  end if;
  if new.converted_client_id is not null and new.converted_at is null then
    new.converted_at := now();
  end if;
  return new;
end;
$$;
drop trigger if exists trg_leads_contacted on public.leads;
create trigger trg_leads_contacted before update on public.leads
  for each row execute function public.stamp_lead_contacted();

alter table public.leads enable row level security;
select public._reset_policies('leads');

-- Staff only. No anon policy by design: the website never touches this table
-- from a browser, so granting public INSERT would create an abuse surface that
-- buys nothing.
create policy leads_staff_all on public.leads for all
  using (public.is_staff()) with check (public.is_staff());


-- ===========================================================================
-- 20260909_08_security_hardening.sql
-- ===========================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra — 08 Security hardening.
--
-- Three findings from the pre-launch audit, all confirmed against the live
-- database. Every one of them is a case of code and schema drifting apart.
--
--  1. prevent_profile_privilege_escalation() pinned role and is_master_admin,
--     but migration 02 later added profiles.client_id and made it the tenancy
--     key for the whole client portal. The trigger was never updated, so any
--     authenticated user could PATCH their own client_id and read another
--     carrier's entire book.
--
--  2. company_settings was readable by every authenticated user. The same row
--     carries billing_settings, which holds Avantra's ACH routing and account
--     numbers. Signup is open, so the audience for those was "anyone with an
--     email address".
--
--  3. login_attempts is read and written by /api/auth/login-track but exists in
--     no migration. The lockout has never worked.
--
-- Depends on 01 and 02. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

set check_function_bodies = off;

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. Pin every column a user must not be able to grant themselves.
--
-- RLS is ROW-level, not column-level: profiles_update lets a user write their
-- own row, and nothing stopped them choosing which columns. role and
-- is_master_admin were pinned; client_id and mfa_enrolled were not.
--
--   client_id    is the tenancy key. app_client_id() reads it, and roughly a
--                dozen portal policies funnel through that — clients,
--                client_drivers, client_equipment, client_onboarding_steps,
--                loads, load_stops, load_check_calls, invoices,
--                client_statements, statement_lines, compliance_items,
--                service_requests, documents. Setting it to another carrier's
--                uuid hands over their loads, rates, invoices, statements,
--                driver CDL numbers and documents.
--
--   mfa_enrolled is what the middleware trusts when deciding whether to force
--                /setup-2fa. Self-attested, it let the account switch off the
--                control that protects it.
--
-- Admin paths are unaffected: /api/users uses the service role, which returns
-- early above.
-- ─────────────────────────────────────────────────────────────────────────────
create or replace function public.prevent_profile_privilege_escalation()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.role() = 'service_role' then
    return new;  -- service role (server, role-checked) may change anything
  end if;
  new.role            := old.role;
  new.is_master_admin := old.is_master_admin;
  new.client_id       := old.client_id;
  new.mfa_enrolled    := old.mfa_enrolled;
  return new;
end;
$$;

drop trigger if exists trg_profiles_priv_esc on public.profiles;
create trigger trg_profiles_priv_esc before update on public.profiles
  for each row execute function public.prevent_profile_privilege_escalation();

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. Close company_settings, and hand out only the two fields that genuinely
--    need to be readable by everyone.
--
-- The old policy was `using (auth.uid() is not null)`, justified by
-- role_permissions being "needed everywhere". That is true, but RLS cannot hand
-- out one column and withhold another — so it also handed out billing_settings.
--
-- SELECT is now admin/back_office only: the settings page is admin, and billing
-- generation is back_office. Everything else reads get_app_config() below.
-- ─────────────────────────────────────────────────────────────────────────────
alter table public.company_settings enable row level security;
select public._reset_policies('company_settings');

create policy company_settings_select on public.company_settings for select
  using (public.has_role('admin', 'back_office'));
create policy company_settings_write on public.company_settings for all
  using (public.has_role('admin')) with check (public.has_role('admin'));

-- The narrow read. Returns ONLY the two non-sensitive fields the app needs on
-- every request — never company_identity and never billing_settings. Being
-- SECURITY DEFINER it bypasses the policy above, which is the entire point:
-- a client-portal or pending user can resolve their permissions and the 2FA
-- requirement without being able to see Avantra's bank details.
create or replace function public.get_app_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(
    (select jsonb_build_object(
              'role_permissions', coalesce(role_permissions, '{}'::jsonb),
              'require_2fa',      coalesce(require_2fa, true))
       from public.company_settings
      order by id
      limit 1),
    jsonb_build_object('role_permissions', '{}'::jsonb, 'require_2fa', true))
$$;

revoke all on function public.get_app_config() from public;
grant execute on function public.get_app_config() to authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. The account-lockout store.
--
-- Columns match exactly what /api/auth/login-track upserts. Only the service
-- role touches this table, so RLS is enabled with NO policies at all: the
-- service role bypasses RLS, and every other caller is denied by default. That
-- also keeps the failed-login history of every user account away from the
-- browser, which is the right posture for it.
-- ─────────────────────────────────────────────────────────────────────────────
create table if not exists public.login_attempts (
  email           text primary key,
  failed_count    integer not null default 0,
  locked_until    timestamptz,
  last_attempt_at timestamptz not null default now()
);

-- Lets a cleanup job find stale rows without a sequential scan.
create index if not exists idx_login_attempts_last on public.login_attempts(last_attempt_at desc);

alter table public.login_attempts enable row level security;
select public._reset_policies('login_attempts');
-- Intentionally no policies. See above.


-- ===========================================================================
-- 20260909_09_money_correctness.sql
-- ===========================================================================

-- ─────────────────────────────────────────────────────────────────────────────
-- Avantra — 09 Money correctness.
--
-- Two audit findings, both about money, both confirmed against the code.
--
--  1. Voiding a fee statement permanently stranded its loads. The uniqueness
--     guard idx_statement_lines_one_fee_per_load has no status predicate, so a
--     fee line reserved its load forever. The invoice side got this right —
--     idx_invoices_one_per_load carries `where ... status <> 'void'`, with the
--     comment "A voided invoice frees the load to be re-invoiced" — but a
--     statement line's status lives on the PARENT row, and a partial index
--     cannot reference another table. Hence the denormalized flag below.
--
--     The consequence was not cosmetic: void a statement cut for the wrong
--     period and those loads can never be billed again through the UI, because
--     the generator's scan excludes any load with a fee line regardless of
--     whether that line's statement still counts. That is Avantra's own revenue
--     silently becoming unbillable.
--
--  2. Recording a second payment OVERWROTE the first. `amount_paid: amt` is a
--     replacement, and "is it paid in full" compared a single remittance
--     against the whole total rather than the outstanding balance. $400 then
--     $600 against a $1,000 statement left amount_paid = 600, status stuck at
--     'partial', $400 of phantom AR on the books, and a client still being
--     chased for money they had already sent. Both sides had it: client
--     statements and broker invoices.
--
--     Accumulating in app code would swap that bug for a lost-update race
--     between two people posting cheques at once, so the read-modify-write
--     happens here, in one statement, under the row lock the UPDATE takes.
--
-- Depends on 03 and 04. Idempotent.
-- ─────────────────────────────────────────────────────────────────────────────

set check_function_bodies = off;

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. Let a voided statement release its loads.
-- ─────────────────────────────────────────────────────────────────────────────
alter table public.statement_lines
  add column if not exists voided boolean not null default false;

-- Anything already sitting under a voided header is released by this backfill.
update public.statement_lines sl
   set voided = true
  from public.client_statements cs
 where sl.statement_id = cs.id
   and cs.status = 'void'
   and sl.voided = false;

-- Swap the guard for one that ignores released lines. Same protection against
-- double-billing a live load; no longer a life sentence.
drop index if exists public.idx_statement_lines_one_fee_per_load;
create unique index if not exists idx_statement_lines_one_fee_per_load
  on public.statement_lines(load_id)
  where load_id is not null and kind = 'fee' and not voided;

-- Keep the flag true to the parent's status, so nobody has to remember to set
-- it and a future void path cannot forget.
create or replace function public.sync_statement_line_void()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status is distinct from old.status then
    update public.statement_lines
       set voided = (new.status = 'void')
     where statement_id = new.id
       and voided is distinct from (new.status = 'void');
  end if;
  return new;
end;
$$;
drop trigger if exists trg_statement_void_lines on public.client_statements;
create trigger trg_statement_void_lines after update on public.client_statements
  for each row execute function public.sync_statement_line_void();

-- A line added to an already-void statement inherits its state rather than
-- re-reserving the load.
create or replace function public.inherit_statement_line_void()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.voided := coalesce(
    (select status = 'void' from public.client_statements where id = new.statement_id),
    false);
  return new;
end;
$$;
drop trigger if exists trg_statement_line_inherit_void on public.statement_lines;
create trigger trg_statement_line_inherit_void before insert on public.statement_lines
  for each row execute function public.inherit_statement_line_void();

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. Payments accumulate, atomically.
--
-- Both functions are SECURITY INVOKER on purpose: the caller's RLS still
-- decides whether they may touch the row. These exist to make the arithmetic
-- correct and race-free, not to widen access.
-- ─────────────────────────────────────────────────────────────────────────────

-- Client → Avantra. This is our revenue.
create or replace function public.record_statement_payment(
  p_statement_id uuid,
  p_amount       numeric,
  p_paid_date    date    default null,
  p_method       text    default null,
  p_reference    text    default null
) returns public.client_statements
language plpgsql security invoker set search_path = public as $$
declare rec public.client_statements;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'Payment amount must be greater than zero';
  end if;

  update public.client_statements s
     set amount_paid       = coalesce(s.amount_paid, 0) + p_amount,
         status            = case
                               when coalesce(s.amount_paid, 0) + p_amount >= s.amount_due
                                 then 'paid'
                               else 'partial'
                             end,
         paid_date         = coalesce(p_paid_date, current_date),
         payment_method    = coalesce(p_method, s.payment_method),
         payment_reference = coalesce(p_reference, s.payment_reference)
   where s.id = p_statement_id
     and s.status <> 'void'
  returning s.* into rec;

  if rec.id is null then
    raise exception 'Statement not found, already voided, or not yours to edit';
  end if;
  return rec;
end;
$$;

-- Broker → the client carrier. NOT our money; we only bill and chase it.
create or replace function public.record_invoice_payment(
  p_invoice_id uuid,
  p_amount     numeric,
  p_paid_date  date    default null,
  p_method     text    default null,
  p_reference  text    default null
) returns public.invoices
language plpgsql security invoker set search_path = public as $$
declare rec public.invoices;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'Payment amount must be greater than zero';
  end if;

  update public.invoices i
     set amount_paid       = coalesce(i.amount_paid, 0) + p_amount,
         status            = case
                               when coalesce(i.amount_paid, 0) + p_amount >= i.amount
                                 then 'paid'
                               else 'partial'
                             end,
         paid_date         = coalesce(p_paid_date, current_date),
         payment_method    = coalesce(p_method, i.payment_method),
         payment_reference = coalesce(p_reference, i.payment_reference)
   where i.id = p_invoice_id
     and i.status <> 'void'
  returning i.* into rec;

  if rec.id is null then
    raise exception 'Invoice not found, already voided, or not yours to edit';
  end if;

  -- Settling the load follows the invoice, and only once it is fully paid.
  -- In the function so it cannot drift out of step with the status above.
  if rec.status = 'paid' and rec.load_id is not null then
    update public.loads set status = 'paid' where id = rec.load_id;
  end if;

  return rec;
end;
$$;
